15: PYCURL_INTERNAL PyThreadState **
16: pycurl_get_thread_state_slot(CurlObject *self)
17: {
18:     /* Get the thread state for callbacks to run in.
19:      * This is either `self->state' when running inside perform() or
20:      * `self->multi_stack->state' when running inside multi_perform().
21:      * When the result is != NULL we also implicitly assert
22:      * a valid `self->handle'.
23:      */
24:     if (self == NULL)
25:         return NULL;
26:     assert(PyObject_IsInstance((PyObject *) self, (PyObject *) p_Curl_Type) == 1);
27:     if (self->state != NULL)
28:     {
29:         /* inside perform() */
30:         assert(self->handle != NULL);
31:         if (self->multi_stack != NULL) {
32:             assert(self->multi_stack->state == NULL);
33:         }
34:         return &self->state;
35:     }
36:     if (self->multi_stack != NULL && self->multi_stack->state != NULL)
37:     {
38:         /* inside multi_perform() */
39:         assert(self->handle != NULL);
40:         assert(self->multi_stack->multi_handle != NULL);
41:         assert(self->state == NULL);
42:         return &self->multi_stack->state;
43:     }
44:     return NULL;
45: }
