48: PYCURL_INTERNAL PyThreadState **
49: pycurl_get_thread_state_slot_multi(CurlMultiObject *self)
50: {
51:     /* Get the thread state for callbacks to run in when given
52:      * multi handles instead of regular handles
53:      */
54:     if (self == NULL)
55:         return NULL;
56:     assert(PyObject_IsInstance((PyObject *) self, (PyObject *) p_CurlMulti_Type) == 1);
57:     if (self->state != NULL)
58:     {
59:         /* inside multi_perform() */
60:         assert(self->multi_handle != NULL);
61:         return &self->state;
